incomes = [num('Incomes', f'C{r}') for r in income_rows]

def compute_tax(income, policies):
    tax = 0
    for lower, upper, rate in policies:
        if income > lower:
            taxable = min(income, upper) - lower if upper else income - lower
            tax += taxable * rate
    return tax

count = 0
for inc in incomes:
    if compute_tax(inc, policies) > 10000:
        count += 1
result = count

