starts = values('Reservations', 'G288:G294')
ends = values('Reservations', 'H288:H294')
minutes = set()
for start, end in zip(starts, ends):
    for m in range(start, end):
        minutes.add(m)

overlap_minutes = set()
all_intervals = list(zip(starts, ends))
for i in range(len(all_intervals)):
    for j in range(i + 1, len(all_intervals)):
        s1, e1 = all_intervals[i]
        s2, e2 = all_intervals[j]
        overlap_start = max(s1, s2)
        overlap_end = min(e1, e2)
        if overlap_start < overlap_end:
            for m in range(overlap_start, overlap_end):
                overlap_minutes.add(m)
result = len(overlap_minutes)
